py_src:
class Solution:
    def countIslands(self, grid: List[List[str]]) -> int:
        rows, cols, count = len(grid), len(grid[0]), 0
        seen = set()
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == "1" and (r, c) not in seen:
                    count += 1
                    stack = [(r, c)]
                    seen.add((r, c))
                    while stack:
                        a, b = stack.pop()
                        for x, y in ((a+1, b), (a-1, b), (a, b+1), (a, b-1)):
                            if 0 <= x < rows and 0 <= y < cols and grid[x][y] == "1" and (x, y) not in seen:
                                seen.add((x, y))
                                stack.append((x, y))
        return count

js_src:
var countIslands = function(grid) {
  const g = grid.map((r) => r.slice()); let n = 0;
  for (let i = 0; i < g.length; i++) for (let j = 0; j < g[0].length; j++) if (g[i][j] === "1") {
    n++; const st = [[i, j]]; g[i][j] = "0";
    while (st.length) { const [a, b] = st.pop(); for (const [x, y] of [[a+1,b],[a-1,b],[a,b+1],[a,b-1]]) if (x >= 0 && y >= 0 && x < g.length && y < g[0].length && g[x][y] === "1") { g[x][y] = "0"; st.push([x, y]); } }
  }
  return n;
};

