class Solution:
    def canGraduate(self, n: int, prereqs: List[List[int]]) -> bool:
        pass

starterCode.javascript:
/**
 * Write your solution here.
 */
var canGraduate = function(n, prereqs) {

};

py_src:
class Solution:
    def canGraduate(self, n: int, prereqs: List[List[int]]) -> bool:
        indeg = [0] * n
        adj = [[] for _ in range(n)]
        for a, b in prereqs:
            adj[b].append(a)
            indeg[a] += 1
        q = deque(i for i in range(n) if indeg[i] == 0)
        seen = 0
        while q:
            x = q.popleft()
            seen += 1
            for y in adj[x]:
                indeg[y] -= 1
                if indeg[y] == 0:
                    q.append(y)
        return seen == n

js_src:
var canGraduate = function(n, prereqs) {
  const indeg = new Array(n).fill(0), adj = Array.from({ length: n }, () => []);
  for (const [a, b] of prereqs) { adj[b].push(a); indeg[a]++; }
  const q = []; for (let i = 0; i < n; i++) if (!indeg[i]) q.push(i);
  let seen = 0;
  while (q.length) { const x = q.shift(); seen++; for (const y of adj[x]) if (--indeg[y] === 0) q.push(y); }
  return seen === n;
};

