class Solution:
    def rainCatcher(self, heights: List[int]) -> int:
        l, r, lm, rm, w = 0, len(heights) - 1, 0, 0, 0
        while l < r:
            if heights[l] < heights[r]:
                lm = max(lm, heights[l]); w += lm - heights[l]; l += 1
            else:
                rm = max(rm, heights[r]); w += rm - heights[r]; r -= 1
